#[test]
fn test_driver_bytes_match_verified_golden() {
    assert_eq!(build_driver(), GOLDEN_DRIVER, "driver bytes diverged from the verified build");
}

#[test]
fn test_track_bytes_match_verified_golden() {
    assert_eq!(build_track(TRACK_LEAD), GOLDEN_TRACK_LEAD);
    assert_eq!(build_track(TRACK_BASS), GOLDEN_TRACK_BASS);
    assert_eq!(build_track(TRACK_ARP), GOLDEN_TRACK_ARP);
}

#[test]
fn test_brr_instruments_match_verified_golden() {
    assert_eq!(encode_brr(&WAVE_LEAD), GOLDEN_BRR_LEAD);
    assert_eq!(encode_brr(&WAVE_BASS), GOLDEN_BRR_BASS);
    assert_eq!(encode_brr(&WAVE_ARP), GOLDEN_BRR_ARP);
}

#[test]
fn test_brr_encoder_uses_prediction_filters() {
    // The point of multi-block instruments is exercising the DSP's
    // prediction filters; make sure the encoder actually picked some.
    let filters: Vec<u8> = [GOLDEN_BRR_LEAD.as_slice(), &GOLDEN_BRR_BASS, &GOLDEN_BRR_ARP]
        .iter()
        .flat_map(|brr| brr.chunks_exact(9).map(|b| (b[0] >> 2) & 0x03))
        .collect();
    assert!(filters.iter().any(|&f| f != 0), "no block used filters 1-3: {filters:?}");
    assert_eq!(filters[0], 0, "loop-start block must be filter 0");
}

#[test]
fn test_tracks_have_equal_duration() {
    let ticks = |trk: &[(u16, u8)]| trk.iter().map(|&(_, t)| t as u32).sum::<u32>();
    let (l, b, a) = (ticks(TRACK_LEAD), ticks(TRACK_BASS), ticks(TRACK_ARP));
    assert!(l == b && b == a, "tracks drift apart: lead {l}, bass {b}, arp {a}");
}

#[test]
fn test_jingle_boots_and_produces_audio() {
    let mut jingle = IdleJingle::new().expect("IPL boot + upload must succeed");

    // One second of audio.
    let samples = jingle.generate(32_000);
    assert_eq!(samples.len(), 32_000 * 2, "stereo interleaved output");
    assert!(
        samples.iter().any(|&s| s != 0),
        "one second in, the jingle should not be silent"
    );
}

#[test]
fn test_first_notes_and_gain_voice() {
    let mut jingle = IdleJingle::new().unwrap();

    // Timer 0 ticks every 16,000 cycles (500 frames); the first notes of
    // all three tracks are fetched on tick 1. 1,000 frames = 2 ticks.
    jingle.generate(1_000);
    let reg = |r| jingle.apu().memory.dsp.read_reg(r);

    // Voice 1 (bass): first note is A2, pitch 0x0385. If this fails while
    // the goldens pass, suspect the SPC700 core reading $FD through
    // `read8` instead of `read8_mut` (timer counter never clears).
    assert_eq!((reg(0x13), reg(0x12)), (0x03, 0x85), "bass first note pitch");

    // Voice 2 (arpeggio) runs on direct GAIN 0x48 -> envelope 0x480, so
    // ENVX (level >> 4) reads back 0x48 while the note sounds.
    assert_eq!(reg(0x28), 0x48, "GAIN voice envelope via ENVX");
}

#[test]
fn test_lead_vibrato_moves_pitch() {
    let mut jingle = IdleJingle::new().unwrap();
    jingle.generate(1_000); // first lead note (E5, 32 ticks) is sounding

    // Sample the voice 0 pitch-low register once per timer tick; the
    // vibrato rewrites it every tick from a 16-step table.
    let mut seen = std::collections::HashSet::new();
    for _ in 0..8 {
        jingle.generate(500); // exactly one 64 Hz tick
        seen.insert(jingle.apu().memory.dsp.read_reg(0x02));
    }
    assert!(
        seen.len() >= 3,
        "vibrato should sweep the pitch register, saw only {seen:?}"
    );
}
